action.code:
if (points.size() < 3) {
        // Handle the case where there are fewer than 3 points
        return Kernel::Plane_3();
    }

    // Calculate the centroid of the points
    Kernel::Point_3 centroid(0, 0, 0);
    for (const auto& point : points) {
        centroid = centroid + point;
    }
    centroid = centroid / points.size();

    // Calculate the covariance matrix
    Kernel::Matrix33 covariance;
    for (const auto& point : points) {
        Kernel::Vector3 vector = point - centroid;
        covariance = covariance + vector * transpose(vector);
    }
    covariance = covariance / points.size();

    // Calculate the normal vector of the plane using the eigenvector corresponding to the smallest eigenvalue
    Kernel::Vector3 normal;
    Kernel::self_adjoint_eigen_solver_3<Kernel::Matrix33> solver;
    solver(covariance, normal);

    // Calculate the plane
    return Kernel::Plane_3(centroid, normal);

