Kernel::Plane_3 compute_best_fitting_plane(const std::list<Kernel::Point_3>& points) {
    if (points.size() < 3) {
        // Handle the case where there are fewer than 3 points
        return Kernel::Plane_3();
    }
    // Calculate the centroid of the points
    Kernel::Point_3 centroid = CGAL::centroid(points.begin(), points.end());
    // Calculate the normal vector of the plane
    Kernel::Vector_3 sum(0, 0, 0);
    for (const auto& point : points) {
        Kernel::Vector_3 vector = point - centroid;
        sum = sum + CGAL::cross_product(vector, vector);
    }
    Kernel::Vector_3 normal = CGAL::null_vector<Kernel::Vector_3>();
